const expiredMessage='Sesi sudah berakhir atau akses dicabut. Masuk kembali dengan Discord.';
function expiredError(){const e=Error(expiredMessage);e.status=401;return e;}
function expireSession(){
 if(sessionInvalid)return;
 sessionInvalid=true;serial++;detailSerial++;
 // Hide existing dashboard, open dialog, print view and notifications immediately.
 // Do not clear an outstanding idempotency key: a submitted order may have committed.
 if($('orderDialog').open)$('orderDialog').close();
 $('sessionExpired').hidden=false;
 document.body.classList.add('session-expired');
 $('sessionExpiredLink').focus();
}
async function api(path,data){
 if(sessionInvalid)throw expiredError();
 if(navigator.onLine===false)throw Error('Tidak ada koneksi internet. Coba lagi setelah terhubung.');
 const options={cache:'no-store',signal:AbortSignal.timeout(15000)};
 if(data!==undefined)Object.assign(options,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});
 const r=await fetch('/api/'+path,options);
 if(r.status===401&&user){expireSession();throw expiredError();}
 const j=await r.json().catch(()=>null);
 if(sessionInvalid)throw expiredError();
 if(!r.ok||!j){const e=Error(j?.error||'Respons server tidak valid.');e.status=r.status;throw e;}
 return j;
}
