let cart=[],cartKey=null;
function orderDraftKey(){return 'nexo-order-draft-v1:'+user.id;}
function persistDraft(){try{localStorage.setItem(orderDraftKey(),JSON.stringify({cart,cartKey,requestKey}));}catch{}}
function restoreDraft(){
 try{
  const d=JSON.parse(localStorage.getItem(orderDraftKey())||'null');if(!d)return;
  if(Array.isArray(d.cart)&&d.cart.length<=5&&d.cart.every(x=>typeof x?.service_id==='string'&&Number.isInteger(x.quantity)&&x.quantity>=1&&x.quantity<=99)&&new Set(d.cart.map(x=>x.service_id)).size===d.cart.length)cart=d.cart;
  if(cart.length&&typeof d.cartKey==='string'&&/^[a-zA-Z0-9_-]{16,80}$/.test(d.cartKey))cartKey=d.cartKey;
  if(typeof d.requestKey?.signature==='string'&&typeof d.requestKey?.id==='string'&&/^[a-zA-Z0-9_-]{16,80}$/.test(d.requestKey.id))requestKey=d.requestKey;
 }catch{}
}
async function shopView(){const host=$('shopBody');host.replaceChildren();const d=await api('customer/saved'),saved=new Set(d.saved);
 const add=id=>{if(cart.some(x=>x.service_id===id)||cart.length>=5)throw Error('Maksimal lima layanan unik.');cart.push({service_id:id,quantity:1});cartKey=null;persistDraft();return shopView();};
 fields(host,'Tambah layanan',[{key:'service_id',label:'Layanan',options:catalog.map(s=>[s.id,s.name+' — '+s.price])}],b=>add(b.service_id));
 const section=node('section','','timeline');section.append(node('h3','Isi keranjang'));let total=0,unknown=0;
 for(const item of cart){const s=catalog.find(x=>x.id===item.service_id),a=node('article','');a.append(node('strong',s?.name||item.service_id),node('p',s?.price||'Tidak tersedia'));if(s?.unit_amount!=null)total+=s.unit_amount*item.quantity;else unknown++;const label=node('label','Jumlah');const input=document.createElement('input');input.type='number';input.min=1;input.max=99;input.value=item.quantity;input.onchange=()=>{const n=Number(input.value);item.quantity=Number.isInteger(n)?Math.max(1,Math.min(99,n)):1;cartKey=null;persistDraft();shopView().catch(e=>status(e.message,true));};label.append(input);a.append(label);button(a,'Hapus',()=>{cart=cart.filter(x=>x!==item);cartKey=null;persistDraft();return shopView();});section.append(a);}
 section.append(node('p','Estimasi: '+money(total)+' · '+unknown+' perlu penawaran.'));
 if(cart.length)button(section,'Ajukan semua order',async()=>{if(!confirm('Buat '+cart.length+' order terpisah?'))return;cartKey??=crypto.randomUUID();persistDraft();const submitting=cartKey;const result=await api('customer/checkout',{request_id:submitting,items:cart});if(cartKey===submitting){cart=[];cartKey=null;persistDraft();}await load();await view('orders');status(result.orders.length+' order berhasil tercatat.');});host.append(section);host.append(node('h3','Favorit akun'));
 for(const s of catalog){const a=node('article','');a.append(node('strong',s.name),node('p',s.price));button(a,saved.has(s.id)?'Hapus favorit':'Simpan favorit',async()=>{await api('customer/saved',{service_id:s.id,saved:!saved.has(s.id)});await shopView();});if(saved.has(s.id))button(a,'Masukkan keranjang',()=>add(s.id));host.append(a);}
}
async function performanceView(){const host=$('performanceBody');host.replaceChildren();const d=await api('performance');if(!d.items.length)host.append(node('p','Belum ada pekerjaan tercatat.'));for(const [idx,x] of d.items.entries()){const a=node('article','');a.append(node('strong',(d.scope==='team'?(idx+1)+'. ':'')+x.display_name),node('p',x.completed+' selesai · '+x.active+' aktif · '+x.overdue+' terlambat'),node('p',x.reviews?'Rating '+x.rating+'/5 dari '+x.reviews+' ulasan':'Belum ada ulasan'));host.append(a);}button(host,'Muat ulang kinerja',()=>performanceView());}
async function view(name){for(const b of document.querySelectorAll('[data-view]'))b.setAttribute('aria-pressed',String(b.dataset.view===name));$('orderLayout').hidden=name!=='orders';$('financeView').hidden=name!=='finance';$('auditView').hidden=name!=='audit';$('teamPanel').hidden=name!=='team';$('workspaceView').hidden=name!=='workspace';$('supportView').hidden=name!=='support';$('reportView').hidden=name!=='report';$('businessView').hidden=name!=='business';$('notificationsView').hidden=name!=='notifications';$('accountView').hidden=name!=='account';$('calendarView').hidden=name!=='calendar';$('shopView').hidden=name!=='shop';$('performanceView').hidden=name!=='performance';if(name==='performance')await performanceView();if(name==='shop')await shopView();if(name==='calendar')await calendarView();if(name==='business')await businessView();if(name==='notifications')await notifications(true);if(name==='account')await accountView();if(name==='workspace')await workspaceView();if(name==='support')await supportView();if(name==='report')await reportView();if(name==='finance')await finance();if(name==='audit')await audit();if(name==='team'){await team();const box=node('section','','timeline');box.id='suspensionPanel';$('suspensionPanel')?.remove();box.append(node('h3','Suspensi akun'),node('p','Akun dengan pekerjaan aktif tidak bisa disuspensi sebelum pekerjaan dialihkan. Semua sesi akun yang disuspensi dicabut.'));fields(box,'Ubah akses akun',[{key:'user_id',label:'Discord ID',max:20},{key:'suspended',label:'Tindakan',options:[['yes','Suspensi'],['no','Aktifkan kembali']]},{key:'reason',label:'Alasan (10–300 karakter)',max:300}],async b=>{if(confirm('Konfirmasi perubahan akses akun?')){await api('team/suspension',{...b,suspended:b.suspended==='yes'});await view('team');}});const d=await api('team/suspension');for(const x of d.items)box.append(node('p',x.user_id+' · '+x.reason));$('teamPanel').append(box);}}
