$('request').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const payload={service_id:$('service').value,quantity:Number($('quantity').value)};const signature=JSON.stringify(payload);if(requestKey?.signature!==signature)requestKey={signature,id:crypto.randomUUID()};persistDraft();const submitting=requestKey.id;const {order}=await api('orders',{...payload,request_id:submitting});if(requestKey?.id===submitting){requestKey=null;persistDraft();}await load();status('Permintaan tercatat: '+order.id);}catch(e){status(e.message,true);}finally{b.disabled=false;}};
